/**
 * Wrap the vendored xterm.js and addon-fit UMD builds into one DSH client
 * chunk (`client/client.xterm.js`).
 *
 * The DSH module loader serves a package-local chunk from
 * `/plugins/<package>/<file>?rev=<rev>` and expects that file to register a
 * factory itself:
 *
 *     window.__ModuleLoader__.load({ id, chunk: '<file>', factory(require) { return exports } })
 *
 * xterm ships as a UMD bundle that prefers CommonJS when a `module` object is
 * in scope, so each library gets its own `module`/`exports` pair inside an
 * IIFE; the factory returns the union of both plus the stylesheet text, which
 * the app injects once after the chunk materializes.
 *
 * The three inputs are byte-for-byte copies of the published packages under
 * `vendor/` (see `vendor/LICENSE.*`). Run with `node scripts/build-chunk.mjs`.
 */
import { readFile, writeFile } from 'node:fs/promises'

const root = new URL('../', import.meta.url)
const read = async path => readFile(new URL(path, root), 'utf8')

/** Drop a trailing `//# sourceMappingURL=` line: the chunk has no sibling map. */
function stripSourceMap(text) {
  return text.replace(/\n?\/\/# sourceMappingURL=[^\n]*\s*$/, '\n')
}

const PACKAGE = 'dsh-terminal-workspace'
const CHUNK = 'client.xterm.js'

const xterm = stripSourceMap(await read('vendor/xterm.js'))
const fit = stripSourceMap(await read('vendor/addon-fit.js'))
const css = await read('vendor/xterm.css')

const out = [
  `/* Generated by scripts/build-chunk.mjs from vendor/*. Do not edit. */`,
  `window.__ModuleLoader__.load({id:\`${PACKAGE}\`,chunk:\`${CHUNK}\`,factory:require=>{`,
  `var out={}`,
  // Each UMD bundle prefers CommonJS when `module` is in scope, so give it one.
  // xterm.js assigns `module.exports = t()`.
  `;(function(){var module={exports:{}};var exports=module.exports;`,
  xterm,
  `out.Terminal=module.exports.Terminal})()`,
  // addon-fit takes the same branch and exports { FitAddon }.
  `;(function(){var module={exports:{}};var exports=module.exports;`,
  fit,
  `out.FitAddon=module.exports.FitAddon})()`,
  `out.css=${JSON.stringify(css)}`,
  `return out`,
  `}})`,
  ``,
].join('\n')

await writeFile(new URL(`client/${CHUNK}`, root), out)
const bytes = Buffer.byteLength(out)
console.log(`wrote client/${CHUNK} (${(bytes / 1024).toFixed(1)} KiB)`)
